#include <stdio.h>
int gcd(int a, int b) {
    while (b) {
        int t=b;
        b=a%b;
        a=t;
    }
    return a;
}
int lcm(int a, int b) {
    return a/gcd(a, b)*b;
}
int main() {
    printf("gcd=%d lcm=%d\n", gcd(48, 18), lcm(4, 6));
    return 0;
}

